# The `show_playlist` API returns the songs in the playlist with their id, title, and artist_ids.
# I will now get the songs from each playlist and check if their title is in old_songs.
# I will collect the songs to remove from each playlist and also collect them to add to the "Archived Songs" playlist later.
songs_to_remove_by_playlist = {}
archived_songs_to_add = []

for playlist in playlists_response:
    playlist_id = playlist["playlist_id"]
    playlist_details = apis.spotify.show_playlist(playlist_id=playlist_id, access_token=spotify_access_token)
    if "songs" in playlist_details:
        for song in playlist_details["songs"]:
            if song["title"] in old_songs:
                if playlist_id not in songs_to_remove_by_playlist:
                    songs_to_remove_by_playlist[playlist_id] = []
                songs_to_remove_by_playlist[playlist_id].append(song)
                archived_songs_to_add.append(song)

print(songs_to_remove_by_playlist, archived_songs_to_add)

